queries.sparql:
PREFIX core: <https://cashtoss.info/ontology#>
PREFIX law: <https://cashtoss.info/ontology/law#>
PREFIX sr: <https://cashtoss.info/ontology/sr#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?safetyRequirement ?article ?articleCode ?lawType ?legalEntity
WHERE {
  ?safetyRequirement a sr:SafetyRequirement ;
                     basedOnSR ?normStatement .

  ?normStatement a core:NormStatement ;
                 hasSourceArticle ?article .

  ?article a law:Article ;
           articleCode ?articleCode ;
           hasLawType ?lawType ;
           belongsToChapter ?chapter .

  ?lawType a law:LawType ;
           rdfs:label ?lawType .

  ?article law:hasLegalEntity ?legalEntity .
}
LIMIT 100

PREFIX guide: <https://cashtoss.info/ontology/guide#>
PREFIX sr: <https://cashtoss.info/ontology/sr#>
PREFIX haz: <https://cashtoss.info/ontology/risk/hazard#>
PREFIX core: <https://cashtoss.info/ontology#>

SELECT DISTINCT ?koshoGuide ?checklistItem ?documentRequirement
WHERE {
  ?koshoGuide a guide:KoshaGuide ;
              hasChecklistItem ?checklistItem .

  ?checklistItem a guide:ChecklistItem ;
                 guide:guideContext ?ctx ;
                 guide:hasBindingForce ?bf .

  ?checklistItem guide:hasDocumentRequirement ?documentRequirement .
  ?documentRequirement a guide:DocumentRequirement .
}
LIMIT 100

PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX core: <https://cashtoss.info/ontology#>

SELECT DISTINCT ?recommendation ?assessmentReport ?hazardFinding ?workContext
WHERE {
  ?recommendation a app:ActionRecommendation .

  ?recommendation app:presentedInAssessmentReport ?assessmentReport .
  OPTIONAL { ?recommendation app:presentedForHazardFinding ?hazardFinding .
             ?hazardFinding a app:HazardFinding . }
  OPTIONAL { ?recommendation app:presentedInWorkContext ?workContext .
             ?workContext a core:WorkContext . }
}
LIMIT 100

PREFIX guide: <https://cashtoss.info/ontology/guide#>
PREFIX sr: <https://cashtoss.info/ontology/sr#>

SELECT DISTINCT ?safetyRequirement ?workProcess ?phase ?processName
WHERE {
  ?safetyRequirement a sr:SafetyRequirement ;
                     guide:hasWorkProcess ?workProcess .

  ?workProcess a guide:WorkProcess ;
               guide:workProcessPhase ?phase ;
               processName ?processName .
}
LIMIT 100

PREFIX sr: <https://cashtoss.info/ontology/sr#>
PREFIX ctx: <https://cashtoss.info/ontology/risk/context#>
PREFIX core: <https://cashtoss.info/ontology#>

SELECT DISTINCT ?safetyRequirement ?ppeState
WHERE {
  ?safetyRequirement a sr:SafetyRequirement ;
                     core:requiresPPEState ?ppeState .

  ?ppeState a ctx:PPEState ;
            core:label ?ppeStateLabel .
}
LIMIT 100

PREFIX core: <https://cashtoss.info/ontology#>
PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX pen: <https://cashtoss.info/ontology/penalty#>

SELECT DISTINCT ?outcome ?criminalSanction ?adminFine
WHERE {
  ?exposure a app:PenaltyExposure .

  # 분석 건에서 사고 결과(AccidentOutcome) 기반으로 연결된 경우
  ?rule a pen:PenaltyRule .
  ?rule pen:hasCondition ?cond .
  ?cond pen:requiresAccidentOutcome ?outcome .

  OPTIONAL {
    ?rule pen:hasSanction ?criminalSanction .
    ?criminalSanction a pen:CriminalSanction .
  }
  OPTIONAL {
    ?rule pen:hasSanction ?adminFine .
    ?adminFine a pen:AdministrativeFine .
  }

  # 실제 instance에서 PenaltyExposure가 PenaltyRule과 연결될 때를 보강(옵션)
  OPTIONAL { ?exposure pen:hasPenaltyRule ?rule . }
}
LIMIT 100
